package com.ecommerce.cart.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.io.Decoders; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService { private final javax.crypto.SecretKey key; public JwtService(@Value("${app.jwt.secret}") String s){byte[] b=Decoders.BASE64.decode(s);if(b.length<32)throw new IllegalArgumentException("JWT secret must decode to at least 32 bytes");key=Keys.hmacShaKeyFor(b);} public String userId(String token){Claims c=Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();if(c.getSubject()==null||c.getSubject().isBlank())throw new JwtException("Missing subject");return c.getSubject();} }